import { Component, OnInit, ChangeDetectorRef } from '@angular/core';

@Component({
  selector: 'app-callback-demo',
  template: `
    <div>
      <h2>Counter: {{ count }}</h2>
      <button (click)="incrementCounter()">Increment with Regular Method</button>
      <button (click)="stableIncrement()">Increment with Stable Callback</button>

      <!-- Add explanatory paragraphs here -->
    </div>
  `
})
export class CallbackDemoComponent implements OnInit {
  count = 0;

  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
  }

  incrementCounter() {
    this.count++;
    this.cdr.detectChanges();
  }

  stableIncrement = () => {
    this.count++;
    this.cdr.detectChanges();
  }
}
